CREATE TABLE IF NOT EXISTS public.gs_arabic_review_history (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  product_id bigint NOT NULL,
  previous_arabic text,
  new_arabic text NOT NULL,
  changed_by uuid NOT NULL REFERENCES auth.users(id),
  changed_at timestamptz NOT NULL DEFAULT now()
);
REVOKE ALL ON TABLE public.gs_arabic_review_history FROM public, anon, authenticated;
ALTER TABLE public.gs_arabic_review_history ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.gs_can_review_arabic()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=''
AS $$ SELECT auth.uid() IS NOT NULL AND (
 EXISTS(SELECT 1 FROM public.gs_arabic_reviewers r WHERE r.user_id=auth.uid() AND r.enabled)
 OR EXISTS(SELECT 1 FROM public.gs_sales_staff s JOIN auth.users u ON u.id=s.user_id
   WHERE s.user_id=auth.uid() AND s.role='admin' AND s.enabled AND lower(u.email)='simon@goldenstarwholesale.net')
) $$;
REVOKE ALL ON FUNCTION public.gs_can_review_arabic() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.gs_can_review_arabic() TO authenticated;

CREATE OR REPLACE FUNCTION public.gs_get_arabic_review_products(p_ids bigint[])
RETURNS TABLE(id bigint, name text, arabic text, sku text, brand text, pick_category text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
BEGIN
 IF NOT public.gs_can_review_arabic() THEN
   RAISE EXCEPTION 'Arabic reviewer access required' USING ERRCODE='42501';
 END IF;
 IF p_ids IS NULL OR cardinality(p_ids)>1000 THEN RAISE EXCEPTION 'Invalid review list'; END IF;
 RETURN QUERY SELECT p.id,p.name,p.arabic,p.sku,p.brand,p.pick_category
 FROM public.gs_sales_products p
 WHERE p.id=ANY(p_ids) AND EXISTS(SELECT 1 FROM public.gs_arabic_review_scope sc WHERE sc.product_id=p.id) AND coalesce(p.pick_category,'')<>'SPICES'
 ORDER BY lower(p.name),p.id;
END $$;
REVOKE ALL ON FUNCTION public.gs_get_arabic_review_products(bigint[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.gs_get_arabic_review_products(bigint[]) TO authenticated;

CREATE OR REPLACE FUNCTION public.gs_save_arabic_review(p_id bigint,p_arabic text)
RETURNS TABLE(id bigint, arabic text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
DECLARE old_name text; new_name text := btrim(coalesce(p_arabic,''));
BEGIN
 IF NOT public.gs_can_review_arabic() THEN
   RAISE EXCEPTION 'Arabic reviewer access required' USING ERRCODE='42501';
 END IF;
 IF char_length(new_name)>500 THEN RAISE EXCEPTION 'Arabic name is too long'; END IF;
 IF new_name='' THEN RAISE EXCEPTION 'Please enter an Arabic name'; END IF;
 IF new_name !~ '[ء-ي]' THEN RAISE EXCEPTION 'Arabic writing is required'; END IF;
 SELECT p.arabic INTO old_name FROM public.gs_sales_products p
 WHERE p.id=p_id AND EXISTS(SELECT 1 FROM public.gs_arabic_review_scope sc WHERE sc.product_id=p.id) AND coalesce(p.pick_category,'')<>'SPICES' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Product unavailable for Arabic review'; END IF;
 IF new_name IS DISTINCT FROM old_name THEN
   UPDATE public.gs_sales_products p SET arabic=new_name WHERE p.id=p_id;
   INSERT INTO public.gs_arabic_review_history(product_id,previous_arabic,new_arabic,changed_by)
   VALUES(p_id,old_name,new_name,auth.uid());
 END IF;
 RETURN QUERY SELECT p.id,p.arabic FROM public.gs_sales_products p WHERE p.id=p_id;
END $$;
REVOKE ALL ON FUNCTION public.gs_save_arabic_review(bigint,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.gs_save_arabic_review(bigint,text) TO authenticated;
COMMIT;

